window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[61]={"id":"061","numero":61,"titre":"Classification des troubles mentaux","objectifs":[{"id":"61-1","rang":"A","rubrique":"Définition","titre":"Connaître les signes, symptômes et syndromes en psychiatrie","contenu":"<p>La sémiologie psychiatrique distingue trois niveaux. Un <strong><span class=\"kw-def\">signe</span></strong> est un élément <em>objectif</em>, observé par le clinicien (mimique figée, ralentissement moteur). Un <strong><span class=\"kw-def\">symptôme</span></strong> est <em>subjectif</em>, rapporté par le patient (tristesse, angoisse, idées intrusives). Un <strong><span class=\"kw-def\">syndrome</span></strong> est un <span class=\"kw-def\">regroupement organisé et cohérent de signes et de symptômes</span> — il oriente le diagnostic mais ne suffit pas, à lui seul, à poser un trouble.</p>\n      <p>L'examen psychiatrique est <strong>clinique</strong> : il explore <strong><span class=\"kw-def\">8 domaines sémiologiques</span></strong> de l'expérience vécue et des conduites du patient, ainsi que leur <span class=\"kw-def\">évolution dans le temps</span>.</p>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> g</span>rands syndromes psychiatriques</strong></p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Caractérisation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Positif</span></td><td>Expérience psychique en « <strong>plus</strong> » : <span class=\"kw-clinique\">idées délirantes</span>, <span class=\"kw-clinique\">hallucinations</span></td></tr>\n          <tr><td><span class=\"kw-def\">Négatif</span></td><td>Expérience psychique « <strong>diminuée</strong> » ou en « moins » (retrait, émoussement affectif)</td></tr>\n          <tr><td><span class=\"kw-def\">Désorganisation</span></td><td>Expérience psychique « <strong>désorganisée</strong> » (pensée, discours, comportement)</td></tr>\n          <tr><td><span class=\"kw-def\">Thymique</span></td><td>Diminution (<span class=\"kw-clinique\">dépressif</span>) ou augmentation (<span class=\"kw-clinique\">maniaque</span>) de l'humeur</td></tr>\n          <tr><td><span class=\"kw-def\">Anxieux</span></td><td>Réaction d'<strong>alerte</strong> de l'organisme</td></tr>\n          <tr><td><span class=\"kw-def\">Dépendance</span></td><td>Difficulté à contrôler un comportement source de plaisir</td></tr>\n          <tr><td><span class=\"kw-def\">Suicidaire</span></td><td><span class=\"kw-alerte\">Mort considérée comme la seule issue</span> de l'épuisement psychique</td></tr>\n          <tr><td><span class=\"kw-def\">Catatonique</span></td><td><span class=\"kw-alerte\">Perturbation grave de l'organisation psychomotrice</span></td></tr>\n          <tr><td><span class=\"kw-def\">Agitation</span></td><td>Augmentation de l'activité motrice</td></tr>\n          <tr><td><span class=\"kw-def\">Chez l'enfant</span></td><td>Plus spécifiquement : syndrome d'<span class=\"kw-clinique\">hyperactivité</span>, d'<span class=\"kw-clinique\">inattention</span>, <span class=\"kw-clinique\">autistique</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> 8 domaines sémiologiques de l'examen psychiatrique</strong></p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Ce qu'on explore</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Présentation / Contact</span></td><td><span class=\"kw-clinique\">Apparence</span> (soignée, négligée, incurie) ; <span class=\"kw-clinique\">mimique</span> (hyper/hypomimie, amimie) ; <span class=\"kw-clinique\">activités psychomotrices</span> (agitation, ralentissement, raptus)</td></tr>\n          <tr><td><span class=\"kw-def\">Discours et pensée</span></td><td><span class=\"kw-clinique\">Langage</span> (dynamique, forme) et <span class=\"kw-clinique\">pensée</span> (dynamique, contenu) — recherche d'un trouble du <em>cours</em> ou du <em>contenu</em> (délire, obsessions)</td></tr>\n          <tr><td><span class=\"kw-def\">Perception</span></td><td><span class=\"kw-clinique\">Hallucinations</span>, <span class=\"kw-clinique\">illusions</span>, modification du seuil de sensibilité, <span class=\"kw-clinique\">déréalisation</span>, <span class=\"kw-clinique\">dépersonnalisation</span></td></tr>\n          <tr><td><span class=\"kw-def\">Attention / Mémoire</span></td><td>Attention (hypoprosexie, distractibilité, hypervigilance) ; mémoire <span class=\"kw-clinique\">épisodique</span> et de <span class=\"kw-clinique\">travail</span> (reviviscences, flashbacks)</td></tr>\n          <tr><td><span class=\"kw-def\">Affectivité</span></td><td><span class=\"kw-clinique\">Émotions</span> (réponses affectives immédiates à un stimulus) et <span class=\"kw-clinique\">humeur</span> (tonalité affective globale et durable)</td></tr>\n          <tr><td><span class=\"kw-def\">Jugement et insight</span></td><td>Qualité du <span class=\"kw-clinique\">jugement</span> et <span class=\"kw-clinique\">conscience du trouble</span> (insight) — oriente la dangerosité et l'indication d'<span class=\"kw-alerte\">hospitalisation</span></td></tr>\n          <tr><td><span class=\"kw-def\">Fonctions physiologiques</span></td><td><span class=\"kw-clinique\">Sommeil</span>, <span class=\"kw-clinique\">alimentation</span>, <span class=\"kw-clinique\">sexualité</span>, signes sympathiques d'anxiété, hyperréactivité neurovégétative</td></tr>\n          <tr><td><span class=\"kw-def\">Comportement</span></td><td>Conduites <span class=\"kw-alerte\">suicidaires</span> ; comportements de <span class=\"kw-ttt\">réduction</span> de l'anxiété (<span class=\"kw-clinique\">évitement</span>, <span class=\"kw-clinique\">compulsion</span>) ; fonctionnement interpersonnel</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Hallucinations — deux familles à distinguer</strong></p>\n      <table >\n        <thead><tr><th>Famille</th><th>Caractère</th><th>Exemples</th><th>Orientation diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Intrapsychiques</span></td>\n            <td>Phénomène vécu <em>dans</em> la pensée, <span class=\"kw-clinique\">sans sensorialité ni spatialité</span>, perçu comme étranger au sujet (« <span class=\"kw-clinique\">perte de l'intimité psychique</span> »)</td>\n            <td>Écho, vol, divulgation, devinement de la pensée, pensée imposée</td>\n            <td>Évocatrices de la <span class=\"kw-etio\">schizophrénie</span> paranoïde</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Sensorielles</span></td>\n            <td>Avec <span class=\"kw-clinique\">sensorialité, spatialité et conviction de réalité</span></td>\n            <td>Auditives (acoustico-verbales), visuelles, tactiles, olfactives, gustatives, cénesthésiques</td>\n            <td>Isolées, elles évoquent plutôt une <span class=\"kw-etio\">hallucinose</span> (cause <span class=\"kw-etio\">toxique</span> ou médicamenteuse)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif · 351 — Agitation et délire aigu · 352 — Crise d'angoisse et attaque de panique · 353 — Risque et conduite suicidaire</em></p>","frequence":4},{"id":"61-2","rang":"B","rubrique":"Définition","titre":"Connaître l’approche catégorielle en psychiatrie","contenu":"<p>L'<strong><span class=\"kw-def\">approche catégorielle</span></strong> classe <span class=\"kw-clinique\">les</span> troubles mentaux en <span class=\"kw-def\">catégories distinctes et nommées</span>, chacune définie par un ensemble de critères. Poser un diagnostic revient à <strong>rattacher le tableau clinique du patient à une (ou plusieurs) catégorie(s)</strong>. C'est l'approche retenue par les grands systèmes nosographiques (<span class=\"kw-def\">DSM-5</span>, <span class=\"kw-def\">CIM-11</span>).</p>\n\n      <p><strong>4 étapes de délimitation</strong> permettent d'aboutir à un diagnostic de trouble mental spécifique et complet :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Démarche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1</span> · Catégorie</td><td>Identifier la <strong><span class=\"kw-def\">grande catégorie nosographique</span></strong> où pourrait se situer la sémiologie recueillie (trouble psychotique, de l'humeur, anxieux…)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span> · Type</td><td>Identifier le <strong>type de trouble</strong> au sein de la catégorie — ex. catégorie « psychotique » → <span class=\"kw-etio\">trouble schizophrénique</span> ou <span class=\"kw-etio\">trouble délirant chronique</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span> · Spécification</td><td><strong>Caractériser / spécifier</strong> le trouble : définir <span class=\"kw-clinique\">les</span> formes cliniques (ex. <span class=\"kw-etio\">schizophrénie</span> « de type paranoïde »)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span> · <span class=\"kw-def\">Comorbidité</span></td><td>Évaluer la <strong><span class=\"kw-def\">comorbidité</span></strong> — elle peut être <span class=\"kw-clinique\">psychiatrique</span>, <span class=\"kw-clinique\">addictive</span> ou <span class=\"kw-clinique\">médicale non psychiatrique</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Le diagnostic multiple est la règle plus que l'exception.</strong> En psychiatrie, on ne s'arrête pas au premier diagnostic. Le <strong><span class=\"kw-def\">diagnostic principal</span></strong> est celui à l'origine de la <span class=\"kw-clinique\">consultation</span> ou de l'<span class=\"kw-clinique\">admission à l'hôpital</span> — il ne dispense <span class=\"kw-ci\">jamais de</span> rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">comorbidités</span> associées.\n      </div>","frequence":0},{"id":"61-3","rang":"A","rubrique":"Définition","titre":"Connaître les critères pour définir un trouble mental","contenu":"<p>Un <strong><span class=\"kw-def\">trouble mental</span></strong> ne se résume pas à un syndrome : son diagnostic repose sur <strong>4 critères</strong> qui doivent tous être réunis.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Sémiologique</span></td><td>Critères sémiologiques <strong>spécifiques</strong> — des <span class=\"kw-clinique\">symptômes</span> et des <span class=\"kw-clinique\">signes</span> le plus souvent organisés en <span class=\"kw-def\">syndromes</span></td></tr>\n          <tr><td><span class=\"kw-def\">Évolution temporelle</span></td><td><span class=\"kw-clinique\">Rupture</span> par rapport à un état antérieur ; <span class=\"kw-def\">critères de</span> <span class=\"kw-chiffre\">durée</span> d'<span class=\"kw-clinique\">évolution</span> des symptômes</td></tr>\n          <tr><td><span class=\"kw-def\">Fonctionnel</span></td><td>Au choix : <strong><span class=\"kw-alerte\">détresse</span> psychologique</strong> (souffrance psychique, altération de la qualité de vie) <em>ou</em> <strong>répercussion fonctionnelle et sociale</strong> (notion de <span class=\"kw-clinique\">handicap</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Élimination d'un DD</span></td><td>Écarter : un <span class=\"kw-etio\">autre trouble mental</span> expliquant mieux le tableau ; un <span class=\"kw-etio\">trouble lié à une substance</span> (intoxication, <span class=\"kw-ttt\">sevrage</span>) ; une <span class=\"kw-etio\">pathologie non psychiatrique</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Le diagnostic en psychiatrie est clinique.</strong> Aucun examen complémentaire n'a une sensibilité ou une spécificité suffisante pour <em>confirmer</em> un trouble mental. <span class=\"kw-clinique\">Les</span> examens complémentaires servent uniquement à <strong>éliminer un <span class=\"kw-def\">diagnostic différentiel</span></strong> (cause <span class=\"kw-etio\">toxique</span>, pathologie médicale non psychiatrique).\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — un syndrome ne suffit pas à poser un trouble.</strong> Un <span class=\"kw-clinique\">syndrome dépressif</span> ne devient <span class=\"kw-etio\">trouble dépressif caractérisé</span> que si <span class=\"kw-clinique\">les</span> critères d'<span class=\"kw-clinique\">évolution</span>, de retentissement et d'élimination des DD sont remplis. Si une <span class=\"kw-etio\">cause médicale non psychiatrique</span> explique mieux le tableau, on parle de <span class=\"kw-alerte\">syndrome dépressif secondaire</span> — pas de trouble.\n      </div>","frequence":0},{"id":"61-4","rang":"B","rubrique":"Définition","titre":"Connaître les systèmes nosographiques existants","contenu":"<p>La <strong><span class=\"kw-def\">nosologie</span></strong> est la science de la <span class=\"kw-def\">classification</span> des maladies ; la <strong><span class=\"kw-def\">nosographie</span></strong> est la classification elle-même, qui en découle. Deux grands systèmes nosographiques coexistent en psychiatrie.</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">CIM-11</span></th><th><span class=\"kw-def\">DSM-5</span></th></tr></thead>\n        <tbody>\n          <tr><td>Rédacteur</td><td><strong><span class=\"kw-def\">OMS</span></strong> — Organisation mondiale de la santé</td><td><strong><span class=\"kw-def\">APA</span></strong> — Association américaine de psychiatrie</td></tr>\n          <tr><td>Maladies concernées</td><td><strong>Toutes <span class=\"kw-clinique\">les</span> maladies</strong>, dont les troubles psychiatriques</td><td><strong>Uniquement</strong> <span class=\"kw-clinique\">les</span> troubles psychiatriques</td></tr>\n          <tr><td>Utilisation de référence</td><td><span class=\"kw-clinique\">Hôpitaux</span> — cotation des actes</td><td><span class=\"kw-clinique\">Recherche</span> psychiatrique</td></tr>\n        </tbody>\n      </table>\n      <p>S'y ajoute la <strong><span class=\"kw-def\">CIF</span></strong> (<span class=\"kw-def\">Classification</span> internationale du fonctionnement), qui n'évalue pas <span class=\"kw-clinique\">les</span> maladies mais leurs <span class=\"kw-clinique\">répercussions fonctionnelles</span>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Il existe de <strong>grandes similitudes</strong> entre <span class=\"kw-def\">CIM-11</span> et <span class=\"kw-def\">DSM-5</span> — leurs différences ne concernent que le spécialiste. Nuance importante : en médecine, la <span class=\"kw-def\">CIM</span> (maladies) et la <span class=\"kw-def\">CIF</span> (fonctionnement) sont <strong>séparées</strong> — la <span class=\"kw-def\">CIM</span> classe <span class=\"kw-clinique\">les</span> maladies selon leur <span class=\"kw-clinique\">physiopathologie sous-jacente</span>, la <span class=\"kw-def\">CIF</span> évalue leurs <span class=\"kw-clinique\">répercussions fonctionnelles</span> ; en psychiatrie au contraire, la définition d'un trouble mental <strong>intègre</strong> les répercussions fonctionnelles des symptômes.\n      </div>","frequence":0},{"id":"61-5","rang":"A","rubrique":"Définition","titre":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","contenu":"<p><span class=\"kw-clinique\">Les</span> troubles mentaux se répartissent en <strong><span class=\"kw-def\">8 grandes catégories nosographiques</span></strong>, communes à l'enfant, l'adolescent et l'adulte. Les situer est la première étape du raisonnement diagnostique catégoriel.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Caractérisation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Troubles du neurodéveloppement</span></td><td>Débutent durant le développement psychomoteur : trouble du développement intellectuel, troubles des <span class=\"kw-clinique\">acquisitions</span> et des <span class=\"kw-clinique\">apprentissages</span>, <span class=\"kw-etio\">TDAH</span>, <span class=\"kw-etio\">TSA</span>, tics</td></tr>\n          <tr><td><span class=\"kw-def\">Troubles psychotiques</span></td><td><span class=\"kw-clinique\">Altération du contact à la réalité</span></td></tr>\n          <tr><td><span class=\"kw-def\">Troubles de l'humeur</span></td><td>Perturbation des <span class=\"kw-clinique\">affects</span> et de leur régulation, avec modifications cognitives et physiologiques associées</td></tr>\n          <tr><td><span class=\"kw-def\">Troubles anxieux</span></td><td><span class=\"kw-clinique\">Anxiété excessive</span> et perturbations comportementales apparentées ; se distinguent par l'objet ou la situation déclenchante</td></tr>\n          <tr><td><span class=\"kw-def\">Trouble obsessionnel compulsif</span></td><td>Idées <span class=\"kw-clinique\">obsessionnelles</span> et comportements de <span class=\"kw-clinique\">compulsions</span></td></tr>\n          <tr><td><span class=\"kw-def\">Troubles à symptomatologie somatique</span></td><td>Prééminence de <span class=\"kw-clinique\">symptômes somatiques</span> inexpliqués par une pathologie non psychiatrique, avec <span class=\"kw-alerte\">détresse</span> ou handicap</td></tr>\n          <tr><td><span class=\"kw-def\">Troubles liés à un traumatisme ou au stress</span></td><td>Symptômes psychiques, cognitifs, comportementaux et neurovégétatifs après exposition à un <span class=\"kw-etio\">événement traumatique</span></td></tr>\n          <tr><td><span class=\"kw-def\">Addictions</span></td><td>Perte de contrôle de l'usage d'un objet de gratification — <span class=\"kw-etio\">substance psychoactive</span> ou <span class=\"kw-etio\">comportement</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Spécificités chez l'enfant.</strong> On retrouve plus spécifiquement le syndrome d'<span class=\"kw-clinique\">hyperactivité</span>, le syndrome d'<span class=\"kw-clinique\">inattention</span> et le syndrome <span class=\"kw-clinique\">autistique</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant · 66 — Trouble dépressif · 67 — Troubles envahissants du développement · 68 — Troubles du comportement de l'ado · 71 — Troubles conduite alimentaire</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.youtube.com/watch?v=uW4Yl447z1c","label":"YouTube — Vidéo psychiatrie générale"}],"cards":[{"i":"602fdf99280b","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Quelles sont les caractéristiques des hallucinations intrapsychiques et sensorielles, et ce qu'elles évoquent sur le plan diagnostique ?","a":"<p>Les hallucinations se distinguent en deux familles :</p><ul><li>Les <strong>hallucinations intrapsychiques</strong> : phénomènes vécus dans la pensée, sans sensorialité ni spatialité, perçus comme étrangers au sujet. Elles sont <strong>évocatrices de la schizophrénie paranoïde</strong> (ex. : écho de la pensée, vol de la pensée).</li><li>Les <strong>hallucinations sensorielles</strong> : phénomènes avec sensorialité, spatialité et conviction de réalité. Isolées, elles évoquent plutôt une <strong>hallucinose</strong> (cause toxique ou médicamenteuse), mais on peut les retrouver dans des pathologies psychiatriques (ex. : auditives, visuelles, tactiles, olfactives, gustatives, cénesthésiques).</li></ul>"},{"i":"69121c69ddc2","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Quels sont les 8 domaines sémiologiques explorés lors de l'examen psychiatrique ?","a":"<p>L'examen psychiatrique explore <strong>8 domaines</strong> principaux de l'expérience vécue et des conduites du patient :</p><ul><li>La <strong>présentation/contact</strong> (apparence, mimique, activités psychomotrices).</li><li>Le <strong>discours et la pensée</strong> (langage, dynamique et contenu de la pensée).</li><li>La <strong>perception</strong> (hallucinations, illusions, déréalisation, dépersonnalisation).</li><li>L'<strong>attention/mémoire</strong> (hypoprosexie, distractibilité, reviviscences).</li><li>L'<strong>affectivité</strong> (émotions, humeur).</li><li>Le <strong>jugement et l'insight</strong> (conscience du trouble).</li><li>Les <strong>fonctions physiologiques</strong> (sommeil, alimentation, sexualité).</li><li>Le <strong>comportement</strong> (conduites suicidaires, comportements de réduction de l'anxiété).</li></ul>"},{"i":"c91572081f32","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Comment les concepts de signe, symptôme et syndrome sont-ils définis en sémiologie psychiatrique ?","a":"<p>En sémiologie psychiatrique, la distinction est la suivante :</p><ul><li>Un <strong>signe</strong> est un élément <strong>objectif</strong>, observable par le clinicien (ex. : mimique figée, ralentissement moteur).</li><li>Un <strong>symptôme</strong> est <strong>subjectif</strong>, rapporté par le patient (ex. : tristesse, angoisse, idées intrusives).</li><li>Un <strong>syndrome</strong> est un regroupement cohérent de signes et de symptômes, orientant le diagnostic mais n'étant pas suffisant pour poser un trouble seul.</li></ul>"},{"i":"4f45fa4f672d","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Pourquoi un syndrome seul ne suffit pas à diagnostiquer un trouble mental selon l'objectif Rang A ?","a":"<p>Un syndrome seul ne suffit pas car, pour poser le diagnostic d'un trouble mental, les <strong>quatre critères</strong> (sémiologique, évolution temporelle, retentissement fonctionnel et élimination des diagnostics différentiels) doivent impérativement être <strong>tous réunis</strong>.</p>"},{"i":"52ad8a9269c6","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Quelle est l'utilité des examens complémentaires dans le diagnostic d'un trouble mental ?","a":"<p>Les examens complémentaires ont pour unique utilité d'<strong>éliminer un diagnostic différentiel</strong>, notamment une cause toxique ou une pathologie médicale non psychiatrique, et non de confirmer directement un trouble mental.</p>"},{"i":"5a61847104b6","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Selon l'objectif Rang A, combien de critères sont nécessaires pour définir un trouble mental et doivent ils tous être réunis ?","a":"<p>Le diagnostic d'un trouble mental repose sur <strong>4 critères</strong> qui doivent <strong>tous être réunis</strong>.</p>"},{"i":"a6c8ca98af2d","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Quels sont les quatre critères indispensables pour définir un trouble mental ?","a":"<ul><li>Le <strong>contenu sémiologique</strong> : il s'agit de symptômes et de signes, souvent organisés en syndromes.</li><li>L'<strong>évolution temporelle</strong> : elle doit marquer une rupture par rapport à un état antérieur, avec des critères de durée spécifiques pour les symptômes.</li><li>L'<strong>impact fonctionnel</strong> : il se manifeste par une détresse psychologique (souffrance psychique, altération de la qualité de vie) ou des répercussions fonctionnelles et sociales (handicap).</li><li>L'<strong>élimination d'un diagnostic différentiel</strong> : il faut écarter un autre trouble mental, un trouble lié à une substance (intoxication, sevrage) ou une pathologie non psychiatrique expliquant mieux le tableau.</li></ul>"},{"i":"01149cb855c8","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Comment définit-on un trouble psychotique ?","a":"<p>Un trouble psychotique est défini par une <strong>altération du contact à la réalité</strong>.</p>"},{"i":"056aad777e57","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Quelles sont les spécificités des troubles mentaux retrouvés chez l'enfant ?","a":"<p>Chez l'enfant, on retrouve plus spécifiquement le <strong>syndrome d'hyperactivité</strong>, le <strong>syndrome d'inattention</strong> et le <strong>syndrome autistique</strong>.</p>"},{"i":"1608253002fa","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Comment caractérise-t-on la catégorie des troubles du neurodéveloppement ?","a":"<p>Les troubles du neurodéveloppement sont caractérisés par un début survenant durant le <strong>développement psychomoteur</strong>. Ils incluent notamment le trouble du développement intellectuel, les troubles des acquisitions et des apprentissages, le <strong>TDAH</strong>, les <strong>TSA</strong> et les tics.</p>"},{"i":"216e1dc48805","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Quelles sont les huit principales catégories nosographiques des troubles mentaux, communes à l'enfant, l'adolescent et l'adulte ?","a":"<p>Les huit principales catégories nosographiques des troubles mentaux sont :</p><ul><li>Les <strong>troubles du neurodéveloppement</strong></li><li>Les <strong>troubles psychotiques</strong></li><li>Les <strong>troubles de l'humeur</strong></li><li>Les <strong>troubles anxieux</strong></li><li>Le <strong>trouble obsessionnel compulsif (TOC)</strong></li><li>Les <strong>troubles à symptomatologie somatique</strong></li><li>Les <strong>troubles liés à un traumatisme ou au stress</strong></li><li>Les <strong>addictions</strong></li></ul>"},{"i":"4648d3ae25c9","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Comment se manifestent les troubles anxieux ?","a":"<p>Les troubles anxieux se manifestent par une <strong>anxiété excessive et des perturbations comportementales</strong> apparentées, se distinguant par l'objet ou la situation déclenchante.</p>"},{"i":"cff31ae67199","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Quelle est la caractéristique principale des troubles de l'humeur ?","a":"<p>Les troubles de l'humeur se caractérisent par une <strong>perturbation des affects et de leur régulation</strong>, avec des modifications cognitives et physiologiques associées.</p>"}]};